const MAX_THREADS = 16;

// `threads` option -> thread count to ask the multi-threaded build for.
function threadsOption(threads) {
	if (threads === 'auto') {
		return Math.min(globalThis.navigator?.hardwareConcurrency || 1, 8);
	}
	if (typeof threads !== 'number' || !Number.isFinite(threads)) {
		throw new TypeError(`LibRaw: threads must be a number or 'auto' (got ${String(threads)})`);
	}
	return Math.min(Math.max(1, Math.floor(threads)), MAX_THREADS);
}

export default class LibRaw {
	/**
	 * What this version of the package supports, for feature detection.
	 */
	static features = Object.freeze({threads: true, maxThreads: MAX_THREADS});

	/**
	 * @param {{threads?: number|'auto'}} [options] Passing `threads` selects the
	 *   multi-threaded build (see readme): up to that many threads when the page
	 *   is cross-origin isolated, one thread otherwise. Without it, the
	 *   single-threaded build is used, as before.
	 *
	 * If the worker (or one of its pool workers) cannot load, every call on the
	 * instance rejects; `await raw.runtimeInfo()` checks this up front.
	 */
	constructor(options) {
		const threaded = options?.threads !== undefined && options?.threads !== null;
		const threads = threaded ? threadsOption(options.threads) : 1;
		this.worker = threaded
			? new Worker(new URL('./worker-threaded.js', import.meta.url), {type:"module"})
			: new Worker(new URL('./worker.js', import.meta.url), {type:"module"});
		this.pending = new Map();      // id -> { resolve, reject }
		this.nextId = 0;
		this.tail = Promise.resolve(); // serializes calls on this (stateful) instance
		this.disposed = false;
		this.failed = null;            // Error once the worker has failed for good
		this.worker.onmessage = ({data}) => {
			let slot = this.pending.get(data?.id);
			if(!slot) {
				return; // unknown or already-settled reply: ignore, never hang
			}
			this.pending.delete(data.id);
			if(data?.error) {
				slot.reject(new Error(data.error));
			} else {
				slot.resolve(data?.out);
			}
		};
		// A worker that fails to load (blocked or missing script, a pool worker
		// that cannot start) never answers, so nothing it was asked would settle.
		this.worker.onerror = (event) => this.fail(event?.message || event?.error?.message || 'the worker could not load or threw');
		this.worker.onmessageerror = () => this.fail('a reply could not be deserialized');
		if(threaded) {
			// The thread pool is sized when the worker instantiates the module,
			// so this is the first call. If it fails, the next call reports it.
			this.runFn('configure', {threads}).catch(()=>{});
		}
	}

	/**
	 * Which build this instance runs and how many threads it decodes with:
	 * `{ threaded, crossOriginIsolated, poolSize, threads }`, as seen from the
	 * worker.
	 */
	async runtimeInfo() {
		return await this.runFn('runtimeInfo');
	}

	// The worker failed for good: reject in-flight calls, and every later one.
	fail(reason) {
		if(this.failed) {
			return;
		}
		this.failed = new Error(`LibRaw worker failed: ${reason}`);
		for(let {reject} of this.pending.values()) {
			reject(this.failed);
		}
		this.pending.clear();
	}

	/**
	 * Dispose of the worker. Rejects any in-flight calls; the instance is unusable afterwards.
	 */
	dispose() {
		this.disposed = true;
		this.worker.terminate();
		for(let {reject} of this.pending.values()) {
			reject(new Error('LibRaw disposed'));
		}
		this.pending.clear();
	}

	runFn(fn, ...args) {
		let exec = () => new Promise((resolve, reject)=>{
			if(this.disposed) { // disposed while queued behind an earlier call
				reject(new Error('LibRaw disposed'));
				return;
			}
			if(this.failed) {
				reject(this.failed);
				return;
			}
			let id = this.nextId++;
			this.pending.set(id, {resolve, reject});
			this.worker.postMessage({id, fn, args}, args.map(a=>{
				if([ArrayBuffer, Uint8Array, Int8Array, Uint16Array, Int16Array, Uint32Array, Int32Array, Float32Array, Float64Array].some(b=>a instanceof b)) { // Transfer buffer
					return a.buffer;
				}
			}).filter(a=>a));
		});
		// Only one call in flight per instance; a rejection must not break the chain.
		let result = this.tail.then(exec, exec);
		this.tail = result.then(()=>{}, ()=>{});
		return result;
	}
	/**
	 * Open/parse the RAW data with optional settings
	 */
	async open(buffer, settings) {
		return await this.runFn('open', buffer, settings);
	}

	/**
	 * Retrieve metadata
	 */
	async metadata(fullOutput) {
		let metadata = await this.runFn('metadata', !!fullOutput);
		// Example: convert numeric thumb_format to a string
		if (metadata?.hasOwnProperty('thumb_format')) {
			metadata.thumb_format = [
				'unknown',
				'jpeg',
				'bitmap',
				'bitmap16',
				'layer',
				'rollei',
				'h265'
			][metadata.thumb_format] || 'unknown';
		}
		// Trim desc if present
		if (metadata?.hasOwnProperty('desc')) {
			metadata.desc = String(metadata.desc).trim();
		}
		if (metadata?.hasOwnProperty('timestamp')) {
			// LibRaw's timestamp is a time_t in epoch seconds; JS Date expects milliseconds.
			metadata.timestamp = new Date(metadata.timestamp * 1000);
		}
		return metadata;
	}

	/**
	 * Retrieve processed image data (synchronously from the perspective of C++,
	 * but we've already awaited the module & instance.)
	 */
	async imageData() {
		return await this.runFn('imageData');
	}

	/**
	 * Retrieve the raw, undebayered sensor data (16-bit mosaic, no demosaicing).
	 */
	async rawImageData() {
		return await this.runFn('rawImageData');
	}

	/**
     * Retrieve the embedded JPEG preview (Fast extraction)
     */
    async thumbnailData() {
        return await this.runFn('thumbnailData');
    }
}